hljs.registerLanguage('toml',function(e){return{name:'TOML',case_insensitive:true,contains:[e.HASH_COMMENT_MODE,{className:'section',begin:/^\s*\[+/,end:/\]+\s*$/},{className:'attr',begin:/^[A-Za-z0-9_.-]+(?=\s*=)/},{className:'string',variants:[e.APOS_STRING_MODE,e.QUOTE_STRING_MODE]},{className:'literal',begin:/\b(true|false)\b/},e.NUMBER_MODE]}});